646	/// Render a path for a human-readable error message. This is used ONLY in
647	/// diagnostics: the filesystem is always given the raw `Path`, never this
648	/// lossy rendering, so a file whose name contains 0xff is not confused with a
649	/// differently named file that merely displays the same way.
650	fn display_path(path: &Path) -> String {
651	    path.to_string_lossy().into_owned()
652	}
