712	/// Split raw bytes into records on LF (0x0a). The separator is not part of
713	/// any record. A trailing LF terminates the last record without adding an
714	/// empty one; an empty file yields zero records.
715	fn split_records(data: &[u8]) -> Vec<&[u8]> {
716	    if data.is_empty() {
717	        return Vec::new();
718	    }
719	    let mut records: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
720	    if data.last() == Some(&b'\n') {
721	        records.pop();
722	    }
723	    records
724	}
