726	/// RFC 6962 section 2.1 leaf hash: SHA-256(0x00 || data). The prefix byte and
727	/// the record are fed to the hasher as two consecutive slices, so hashing a
728	/// record of any length needs no copy of the record and no allocation beyond
729	/// the hasher's fixed-size state.
730	fn leaf_hash(data: &[u8]) -> [u8; 32] {
731	    let mut h = Sha256::new();
732	    h.update(&[0x00]);
733	    h.update(data);
734	    h.finalize()
735	}
