737	/// RFC 6962 section 2.1 interior node hash: SHA-256(0x01 || left || right).
738	fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
739	    let mut h = Sha256::new();
740	    h.update(&[0x01]);
741	    h.update(left);
742	    h.update(right);
743	    h.finalize()
744	}
