746	/// Construct the RFC 6962 Merkle tree over a batch. This is the SINGLE place
747	/// that maintains the tree-construction rules: both `root` (via `mth`) and
748	/// `prove` (via `root_and_path`) build their leaves and subtrees here, so the
749	/// two commands can never disagree on how a batch is shaped or hashed.
750	///
751	/// ```text
752	/// MTH([])      = SHA-256("")
753	/// MTH([d])     = SHA-256(0x00 || d)
754	/// MTH(d0..dn)  = SHA-256(0x01 || MTH(d0..dk) || MTH(dk..dn))
755	/// ```
756	///
757	/// with k the largest power of two strictly smaller than n. Uneven batches
758	/// are handled by the recursion itself: no leaf is duplicated and no empty
759	/// record is appended to round the size up to a power of two.
760	///
761	/// `target` selects the one leaf a membership proof is built for:
762	///
763	/// ```text
764	/// PATH(m, [d0]) = []
765	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
766	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
767	/// ```
768	///
769	/// When `target` is `Some(m)`, the sibling subtree hashes on the route from
770	/// leaf `m` to the root are appended to `path` in leaf-to-root order
771	/// (RFC 6962 section 2.1.1); the reindexed `Some(m - k)` follows the audited
772	/// leaf into whichever subtree contains it, while the sibling subtree is
773	/// built with `None`. With `None` only the root is built. Every leaf hash and
774	/// every interior hash is computed exactly once in either mode, so producing
775	/// a proof costs the same 2n - 1 SHA-256 invocations as the root alone.
776	fn build_tree(
777	    leaves: &[&[u8]],
778	    target: Option<usize>,
779	    path: &mut Vec<[u8; 32]>,
780	) -> [u8; 32] {
781	    match leaves.len() {
782	        0 => sha256(&[]),
783	        1 => leaf_hash(leaves[0]),
784	        n => {
785	            // Largest power of two strictly smaller than n.
786	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
787	            let (left_leaves, right_leaves) = leaves.split_at(k);
788	            match target {
789	                // The audited leaf is in the left subtree; the right subtree
790	                // hash is this level's sibling on the leaf-to-root path.
791	                Some(m) if m < k => {
792	                    let left = build_tree(left_leaves, Some(m), path);
793	                    let right = build_tree(right_leaves, None, path);
794	                    path.push(right);
795	                    node_hash(&left, &right)
796	                }
797	                // The audited leaf is in the right subtree; reindex it
798	                // relative to that subtree and take the left subtree as the
799	                // sibling.
800	                Some(m) => {
801	                    let left = build_tree(left_leaves, None, path);
802	                    let right = build_tree(right_leaves, Some(m - k), path);
803	                    path.push(left);
804	                    node_hash(&left, &right)
805	                }
806	                // No audited leaf: both subtrees are plain root constructions.
807	                None => {
808	                    let left = build_tree(left_leaves, None, path);
809	                    let right = build_tree(right_leaves, None, path);
810	                    node_hash(&left, &right)
811	                }
812	            }
813	        }
814	    }
815	}
