817	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256: the batch root, built
818	/// by the shared `build_tree` constructor so it follows exactly the same
819	/// rules as proof generation.
820	fn mth(leaves: &[&[u8]]) -> [u8; 32] {
821	    build_tree(leaves, None, &mut Vec::new())
822	}
