824	/// RFC 6962 section 2.1.1: the Merkle Tree Hash of the whole batch together
825	/// with the Merkle Audit Path for the record at `m`, both produced by the
826	/// shared `build_tree` constructor. The returned path is ordered from the
827	/// leaf level up to the root and is empty for a batch of exactly one record.
828	fn root_and_path(leaves: &[&[u8]], m: usize) -> ([u8; 32], Vec<[u8; 32]>) {
829	    let n = leaves.len();
830	    assert!(m < n, "leaf index {m} out of range for {n} record(s)");
831	    let mut path = Vec::new();
832	    let root = build_tree(leaves, Some(m), &mut path);
833	    (root, path)
834	}
