836	fn hex(digest: &[u8; 32]) -> String {
837	    let mut s = String::with_capacity(64);
838	    for b in digest {
839	        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
840	        s.push(char::from_digit((b & 0x0f) as u32, 16).unwrap());
841	    }
842	    s
843	}
