876	/// Streaming SHA-256 (FIPS 180-4). The working state is the eight hash words
877	/// plus one 64-byte block buffer, so the temporary memory a hash needs is a
878	/// small constant no matter how long the hashed input is: a record is fed in
879	/// place from the batch buffer and is never copied for hashing.
880	struct Sha256 {
881	    h: [u32; 8],
882	    buf: [u8; 64],
883	    buf_len: usize,
884	    total_len: u64,
885	}
886	
887	impl Sha256 {
888	    fn new() -> Self {
889	        #[cfg(test)]
890	        SHA256_CALLS.with(|c| c.set(c.get() + 1));
891	        Sha256 {
892	            h: [
893	                0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c,
894	                0x1f83d9ab, 0x5be0cd19,
895	            ],
896	            buf: [0u8; 64],
897	            buf_len: 0,
898	            total_len: 0,
899	        }
900	    }
901	
902	    /// Feed the next chunk of input. Bytes are consumed straight from `data`;
903	    /// only a partial trailing block is ever staged in `buf`.
904	    fn update(&mut self, mut data: &[u8]) {
905	        self.total_len = self.total_len.wrapping_add(data.len() as u64);
906	        if self.buf_len > 0 {
907	            let take = (64 - self.buf_len).min(data.len());
908	            self.buf[self.buf_len..self.buf_len + take].copy_from_slice(&data[..take]);
909	            self.buf_len += take;
910	            data = &data[take..];
911	            if self.buf_len == 64 {
912	                let block = self.buf;
913	                self.compress(&block);
914	                self.buf_len = 0;
915	            }
916	        }
917	        while data.len() >= 64 {
918	            let (block, rest) = data.split_at(64);
919	            let mut staged = [0u8; 64];
920	            staged.copy_from_slice(block);
921	            self.compress(&staged);
922	            data = rest;
923	        }
924	        if !data.is_empty() {
925	            self.buf[..data.len()].copy_from_slice(data);
926	            self.buf_len = data.len();
927	        }
928	    }
929	
930	    /// Append the FIPS 180-4 padding (0x80, zeros, 64-bit big-endian bit
931	    /// length) inside the block buffer and produce the digest. At most one
932	    /// extra block is needed when the length field does not fit after the
933	    /// final data byte.
934	    fn finalize(mut self) -> [u8; 32] {
935	        let bit_len = self.total_len.wrapping_mul(8);
936	        self.update(&[0x80]);
937	        while self.buf_len != 56 {
938	            self.update(&[0]);
939	        }
940	        self.update(&bit_len.to_be_bytes());
941	        debug_assert_eq!(self.buf_len, 0, "padding must end on a block boundary");
942	
943	        let mut out = [0u8; 32];
944	        for (i, word) in self.h.iter().enumerate() {
945	            out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
946	        }
947	        out
948	    }
949	
950	    /// The SHA-256 compression function over one 64-byte block.
951	    fn compress(&mut self, block: &[u8; 64]) {
952	        let mut w = [0u32; 64];
953	        for (i, word) in block.chunks_exact(4).enumerate() {
954	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
955	        }
956	        for i in 16..64 {
957	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
958	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
959	            w[i] = w[i - 16]
960	                .wrapping_add(s0)
961	                .wrapping_add(w[i - 7])
962	                .wrapping_add(s1);
963	        }
964	
965	        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = self.h;
966	        for i in 0..64 {
967	            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
968	            let ch = (e & f) ^ ((!e) & g);
969	            let t1 = hh
970	                .wrapping_add(s1)
971	                .wrapping_add(ch)
972	                .wrapping_add(K[i])
973	                .wrapping_add(w[i]);
974	            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
975	            let maj = (a & b) ^ (a & c) ^ (b & c);
976	            let t2 = s0.wrapping_add(maj);
977	            hh = g;
978	            g = f;
979	            f = e;
980	            e = d.wrapping_add(t1);
981	            d = c;
982	            c = b;
983	            b = a;
984	            a = t1.wrapping_add(t2);
985	        }
986	
987	        self.h[0] = self.h[0].wrapping_add(a);
988	        self.h[1] = self.h[1].wrapping_add(b);
989	        self.h[2] = self.h[2].wrapping_add(c);
990	        self.h[3] = self.h[3].wrapping_add(d);
991	        self.h[4] = self.h[4].wrapping_add(e);
992	        self.h[5] = self.h[5].wrapping_add(f);
993	        self.h[6] = self.h[6].wrapping_add(g);
994	        self.h[7] = self.h[7].wrapping_add(hh);
995	    }
996	}
