1060	        // Input long enough to span several blocks, including NUL, CR and
1061	        // non-UTF-8 bytes; every split into chunks must give the one-shot
1062	        // digest, so no chunk boundary can drop, duplicate or reorder a byte.
1063	        let mut input = Vec::new();
1064	        for i in 0..300u32 {
1065	            input.extend_from_slice(&i.to_be_bytes());
1066	            input.extend_from_slice(b"\x00\xff\rrec\n");
1067	        }
1068	        let want = sha256(&input);
1069	        for chunk in [1usize, 2, 3, 55, 56, 63, 64, 65, 127, 128, 1000] {
1070	            let mut h = Sha256::new();
1071	            for piece in input.chunks(chunk) {
1072	                h.update(piece);
1073	            }
1074	            assert_eq!(hex_of(&h.finalize()), hex_of(&want), "chunk size {chunk}");
1075	        }
1076	        // Byte-at-a-time feeding of the padding-boundary lengths 54..=66.
1077	        for len in 54..=66usize {
1078	            let data: Vec<u8> = (0..len as u8).map(|b| b.wrapping_mul(37).wrapping_add(1)).collect();
1079	            let mut h = Sha256::new();
1080	            for b in &data {
1081	                h.update(&[*b]);
1082	            }
1083	            assert_eq!(hex_of(&h.finalize()), hex_of(&sha256(&data)), "len {len}");
1084	        }
1085	    }
