1147	    fn audit_paths_verify_at_every_position_for_many_sizes() {
1148	        // Sizes both sides of several power-of-two boundaries (uneven sizes
1149	        // must not pad with empty or duplicated trailing records).
1150	        let sizes: Vec<usize> = (1..=18).chain([31, 32, 33, 63, 64, 65, 100, 127, 128, 129, 257]).collect();
1151	        for n in sizes {
1152	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
1153	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
1154	            let root = mth(&refs);
1155	            for m in 0..n {
1156	                let (fused_root, path) = root_and_path(&refs, m);
1157	                assert_eq!(
1158	                    hex_of(&fused_root),
1159	                    hex_of(&root),
1160	                    "single-pass root must equal mth at n={n}, m={m}"
1161	                );
1162	                if n == 1 {
1163	                    assert!(path.is_empty(), "single record must have an empty path");
1164	                } else {
1165	                    // Path length is bounded by the tree depth; for an even
1166	                    // power-of-two batch every position sits at full depth.
1167	                    let depth = usize::BITS - (n - 1).leading_zeros();
1168	                    if n.is_power_of_two() {
1169	                        assert_eq!(path.len(), depth as usize, "n={n}, m={m}");
1170	                    } else {
1171	                        assert!(path.len() <= depth as usize, "n={n}, m={m}");
1172	                    }
1173	                }
1174	                let computed = rfc_recompute_root(refs[m], m, n, &path);
1175	                assert_eq!(hex_of(&computed), hex_of(&root), "proof mismatch at n={n}, m={m}");
1176	            }
1177	        }
1178	    }
