1181	    fn proof_generation_hashes_every_leaf_and_subtree_exactly_once() {
1182	        // A batch of n records has n leaf hashes and n - 1 interior node
1183	        // hashes. Computing the root and one audit path in a single pass must
1184	        // cost exactly 2n - 1 SHA-256 invocations: the old two-phase
1185	        // implementation (mth for the root, then inclusion_path recomputing
1186	        // the sibling subtrees) needed strictly more for any n >= 2.
1187	        for n in [1usize, 2, 3, 4, 5, 8, 9, 10, 16, 33] {
1188	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
1189	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
1190	            for m in 0..n {
1191	                SHA256_CALLS.with(|c| c.set(0));
1192	                let _ = root_and_path(&refs, m);
1193	                let calls = SHA256_CALLS.with(|c| c.get());
1194	                assert_eq!(
1195	                    calls,
1196	                    2 * n - 1,
1197	                    "n={n}, m={m}: expected {n} leaf + {} interior hashes, each computed once",
1198	                    n - 1
1199	                );
1200	            }
1201	        }
