1359	
1360	        let drop_field = |bytes: &[u8], needle: &str| -> Vec<u8> {
1361	            let text = String::from_utf8(bytes.to_vec()).unwrap();
1362	            // Rebuild without the named member by string surgery on the
1363	            // canonical compact form emitted by proof_json.
1364	            let idx = text.find(needle).unwrap();
1365	            let mut end = idx + needle.len();
1366	            // Consume through the member's value terminator.
1367	            match needle {
1368	                "\"tree_size\":" | "\"leaf_index\":" => {
1369	                    while end < text.len()
1370	                        && text.as_bytes()[end] != b','
1371	                        && text.as_bytes()[end] != b'}'
1372	                    {
1373	                        end += 1;
1374	                    }
1375	                }
1376	                "\"root\":" => {
1377	                    while end < text.len() && text.as_bytes()[end] != b'"' {
1378	                        end += 1;
1379	                    }
1380	                    end += 1;
1381	                }
1382	                _ => {
1383	                    end = text.rfind(']').unwrap() + 1;
1384	                }
1385	            }
