1388	            let rest = &text[end..];
1389	            // Tidy the separator left by the removed member.
1390	            if rest.starts_with(',') {
1391	                s.push_str(&rest[1..]);
1392	            } else if text[..idx].ends_with(',') {
1393	                s.pop();
1394	                s.push_str(rest);
1395	            } else {
1396	                s.push_str(rest);
1397	            }
1398	            s.into_bytes()
1399	        };
